import{_ as e,c as i,o as t,a2 as s}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"隱私選擇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy-choices.md","filePath":"zh-TW/guide/privacy-choices.md","lastUpdated":1793163976000}'),r={name:"zh-TW/guide/privacy-choices.md"};function p(l,a,o,h,n,c){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="隱私選擇" tabindex="-1">隱私選擇 <a class="header-anchor" href="#隱私選擇" aria-label="Permalink to &quot;隱私選擇&quot;">​</a></h1><p>NueZip 是一款完全離線的應用程式。由於您的所有資料都保留在裝置上，我們不會蒐集、販售或分享任何個人資訊。</p><h2 id="我們在本機持有的資料" tabindex="-1">我們在本機持有的資料 <a class="header-anchor" href="#我們在本機持有的資料" aria-label="Permalink to &quot;我們在本機持有的資料&quot;">​</a></h2><p>NueZip 將所有資料儲存在您 Mac 的本機上：</p><ul><li>App 偏好與設定</li><li>最近檔案清單</li><li>除錯日誌（若已啟用）</li><li>儲存在鑰匙圈中的密碼（若您選擇儲存）</li></ul><p>這些資料都不會被上傳到任何伺服器。</p><h2 id="您的權利" tabindex="-1">您的權利 <a class="header-anchor" href="#您的權利" aria-label="Permalink to &quot;您的權利&quot;">​</a></h2><p>由於 NueZip 不會在我們的伺服器上蒐集或儲存個人資料，因此我們沒有可存取、刪除或移轉的個人資料。您所有資料都可以直接在 App 內管理，或是透過移除 App 的 container 資料夾來處理：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><h2 id="不販售" tabindex="-1">不販售 <a class="header-anchor" href="#不販售" aria-label="Permalink to &quot;不販售&quot;">​</a></h2><p>NueZip 不販售任何個人資訊。我們不使用任何形式的第三方分析、廣告或追蹤服務。</p><h2 id="聯絡方式" tabindex="-1">聯絡方式 <a class="header-anchor" href="#聯絡方式" aria-label="Permalink to &quot;聯絡方式&quot;">​</a></h2><p>若您對隱私選擇有任何疑問，請在以下位置開立 issue： <code>https://github.com/nuezip/nuezip/issues</code></p>',13)])])}const _=e(r,[["render",p]]);export{u as __pageData,_ as default};
